import unittest
from solution import gcd

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(gcd(12, 18), 6)
    def test_coprime(self):
        self.assertEqual(gcd(7, 13), 1)
    def test_zero(self):
        self.assertEqual(gcd(0, 5), 5)
    def test_equal(self):
        self.assertEqual(gcd(9, 9), 9)
